create extension if not exists "pgcrypto";
create table if not exists public.profiles (id uuid primary key references auth.users on delete cascade, display_name text not null default 'Shopper', role text not null default 'buyer' check(role in ('buyer','seller','admin')), seller_approved boolean not null default false, avatar_url text, created_at timestamptz default now());
create table if not exists public.products (id uuid primary key default gen_random_uuid(), seller_id uuid references public.profiles(id), title text not null, description text, price numeric(10,2) not null default 0, starting_bid numeric(10,2), image_url text, status text not null default 'active', stock int not null default 1, created_at timestamptz default now());
create table if not exists public.shows (id uuid primary key default gen_random_uuid(), seller_id uuid references public.profiles(id), title text not null, room_name text unique not null, starts_at timestamptz, status text not null default 'scheduled', cover_url text, created_at timestamptz default now());
create table if not exists public.bids (id bigint generated always as identity primary key, show_id uuid references public.shows on delete cascade, product_id uuid references public.products, bidder_id uuid references public.profiles, amount numeric(10,2) not null check(amount>0), created_at timestamptz default now());
create table if not exists public.messages (id bigint generated always as identity primary key, show_id uuid references public.shows on delete cascade, user_id uuid references public.profiles, body text not null check(char_length(body)<=500), created_at timestamptz default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), buyer_id uuid references public.profiles, seller_id uuid references public.profiles, product_id uuid references public.products, total numeric(10,2) not null, platform_fee numeric(10,2) generated always as (round(total*0.05,2)) stored, seller_net numeric(10,2) generated always as (round(total*0.95,2)) stored, status text not null default 'pending', tracking_number text, created_at timestamptz default now());
create table if not exists public.follows (follower_id uuid references public.profiles on delete cascade, seller_id uuid references public.profiles on delete cascade, created_at timestamptz default now(), primary key(follower_id,seller_id));
create table if not exists public.giveaways (id uuid primary key default gen_random_uuid(), show_id uuid references public.shows on delete cascade, title text not null, winner_id uuid references public.profiles, status text default 'open', created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.products enable row level security; alter table public.shows enable row level security; alter table public.bids enable row level security; alter table public.messages enable row level security; alter table public.orders enable row level security; alter table public.follows enable row level security; alter table public.giveaways enable row level security;
create policy "public profiles" on public.profiles for select using(true); create policy "own profile" on public.profiles for update using(auth.uid()=id);
create policy "public products" on public.products for select using(true); create policy "seller products" on public.products for all using(auth.uid()=seller_id) with check(auth.uid()=seller_id);
create policy "public shows" on public.shows for select using(true); create policy "seller shows" on public.shows for all using(auth.uid()=seller_id) with check(auth.uid()=seller_id);
create policy "public bids" on public.bids for select using(true); create policy "place bids" on public.bids for insert with check(auth.uid()=bidder_id);
create policy "public chat" on public.messages for select using(true); create policy "send chat" on public.messages for insert with check(auth.uid()=user_id);
create policy "order parties" on public.orders for select using(auth.uid()=buyer_id or auth.uid()=seller_id); create policy "buyer order" on public.orders for insert with check(auth.uid()=buyer_id);
create policy "public follows" on public.follows for select using(true); create policy "own follows" on public.follows for all using(auth.uid()=follower_id) with check(auth.uid()=follower_id);
create policy "public giveaways" on public.giveaways for select using(true);
create or replace function public.new_user_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1))) on conflict do nothing; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.new_user_profile();
alter publication supabase_realtime add table public.bids, public.messages, public.shows;
